def inr_format(n):
    s = str(n)
    reversed_s = s[::-1]
    grouped = []
    for i in range(0, len(reversed_s), 2):
        grouped.append(reversed_s[i:i+2])
    grouped.reverse()
    return ','.join(grouped)

